SELECT DISTINCT t0."id" AS "decision" FROM "decision__state" AS t0 WHERE t0."v" = 'proposed';

CREATE MATERIALIZED VIEW "proposal__witness" AS
SELECT DISTINCT t0."id" AS "v_d" FROM "decision__state" AS t0 WHERE t0."v" = 'proposed';

