SELECT DISTINCT t0."household" AS "household", t0."n" AS "n" FROM "application_count" AS t0 WHERE t0."n" >= CAST(2 AS BIGINT);

CREATE MATERIALIZED VIEW "repeat_application__witness" AS
SELECT DISTINCT t0."household" AS "v_h", t0."n" AS "v_n" FROM "application_count" AS t0 WHERE t0."n" >= CAST(2 AS BIGINT);

CREATE MATERIALIZED VIEW "took_effect" AS
SELECT DISTINCT t0."id" AS "decision", t1."id" AS "on" FROM "decision" AS t0 JOIN "reference_date__day" AS t1 ON TRUE JOIN "decision__valid_from_day" AS t2 ON t2."id" = t0."id" LEFT JOIN "decision__state" AS n0 ON n0."id" = t0."id" AND n0."v" = 'proposed' WHERE t2."v" <= t1."v" AND n0."id" IS NULL;

CREATE MATERIALIZED VIEW "replaced" AS
SELECT DISTINCT t0."v" AS "decision", t0."id" AS "by", t1."on" AS "on" FROM "decision__supersedes" AS t0 JOIN "took_effect" AS t1 ON t1."decision" = t0."id";

CREATE MATERIALIZED VIEW "replaced__witness" AS
SELECT DISTINCT t0."v" AS "v_d", t1."on" AS "v_r", t0."id" AS "v_s" FROM "decision__supersedes" AS t0 JOIN "took_effect" AS t1 ON t1."decision" = t0."id";

DECLARE RECURSIVE VIEW "replaces" ("a" VARCHAR NOT NULL, "b" VARCHAR NOT NULL);

CREATE MATERIALIZED VIEW "replaces" AS
SELECT DISTINCT t0."id" AS "a", t0."v" AS "b" FROM "decision__supersedes" AS t0
UNION
SELECT DISTINCT t0."a" AS "a", t1."v" AS "b" FROM "replaces" AS t0 JOIN "decision__supersedes" AS t1 ON t1."id" = t0."b";

CREATE MATERIALIZED VIEW "scoped" AS
SELECT DISTINCT t0."id" AS "statement" FROM "identity_statement__first_node" AS t0 JOIN "identity_statement__second_node" AS t1 ON t1."id" = t0."id" JOIN "statement_scope" AS t2 ON t2."statement" = t0."id" AND t2."node" = t0."v" JOIN "statement_scope" AS t3 ON t3."statement" = t0."id" AND t3."node" = t1."v";

CREATE MATERIALIZED VIEW "series_across_axes" AS
