SELECT DISTINCT t0."id" AS "v_v0" FROM "evaluation_day" AS t0;

CREATE MATERIALIZED VIEW "std_time_reference_point_horizon" AS
SELECT DISTINCT t0."id" AS "id", t0."v" AS "v" FROM "reference_point__horizon" AS t0
UNION
SELECT DISTINCT t0."id" AS "id", t1."v" AS "v" FROM "evaluation_day" AS t0 JOIN "evaluation_day__horizon" AS t1 ON t1."id" = t0."id";

CREATE MATERIALIZED VIEW "std_time_reference_point_horizon_1__witness" AS
SELECT DISTINCT t0."id" AS "v_v0", t0."v" AS "v_v1" FROM "reference_point__horizon" AS t0;

CREATE MATERIALIZED VIEW "std_time_reference_point_horizon_2__witness" AS
SELECT DISTINCT t0."id" AS "v_v0", t1."v" AS "v_v1" FROM "evaluation_day" AS t0 JOIN "evaluation_day__horizon" AS t1 ON t1."id" = t0."id";

CREATE MATERIALIZED VIEW "std_time_reference_point_horizon_out_of_range" AS
SELECT DISTINCT t0."id" AS "id" FROM "evaluation_day" AS t0 JOIN "evaluation_day__horizon" AS t1 ON t1."id" = t0."id" WHERE t1."v" < CAST(0 AS BIGINT);

CREATE MATERIALIZED VIEW "std_time_reference_point_position_no_day" AS
SELECT DISTINCT t0."id" AS "id" FROM "evaluation_day" AS t0 JOIN "reference_date__day" AS t1 ON t1."id" = t0."id" WHERE ((t1."v" - ((t1."v" / CAST(10000 AS BIGINT)) * CAST(10000 AS BIGINT))) / CAST(100 AS BIGINT)) < CAST(1 AS BIGINT)
UNION
SELECT DISTINCT t0."id" AS "id" FROM "evaluation_day" AS t0 JOIN "reference_date__day" AS t1 ON t1."id" = t0."id" WHERE ((t1."v" - ((t1."v" / CAST(10000 AS BIGINT)) * CAST(10000 AS BIGINT))) / CAST(100 AS BIGINT)) = CAST(2 AS BIGINT) AND ((t1."v" - ((t1."v" / CAST(10000 AS BIGINT)) * CAST(10000 AS BIGINT))) - (((t1."v" - ((t1."v" / CAST(10000 AS BIGINT)) * CAST(10000 AS BIGINT))) / CAST(100 AS BIGINT)) * CAST(100 AS BIGINT))) = CAST(29 AS BIGINT) AND ((t1."v" / CAST(10000 AS BIGINT)) - (((t1."v" / CAST(10000 AS BIGINT)) / CAST(4 AS BIGINT)) * CAST(4 AS BIGINT))) <> CAST(0 AS BIGINT)
UNION
SELECT DISTINCT t0."id" AS "id" FROM "evaluation_day" AS t0 JOIN "reference_date__day" AS t1 ON t1."id" = t0."id" WHERE ((t1."v" - ((t1."v" / CAST(10000 AS BIGINT)) * CAST(10000 AS BIGINT))) / CAST(100 AS BIGINT)) = CAST(2 AS BIGINT) AND ((t1."v" - ((t1."v" / CAST(10000 AS BIGINT)) * CAST(10000 AS BIGINT))) - (((t1."v" - ((t1."v" / CAST(10000 AS BIGINT)) * CAST(10000 AS BIGINT))) / CAST(100 AS BIGINT)) * CAST(100 AS BIGINT))) = CAST(29 AS BIGINT) AND ((t1."v" / CAST(10000 AS BIGINT)) - (((t1."v" / CAST(10000 AS BIGINT)) / CAST(100 AS BIGINT)) * CAST(100 AS BIGINT))) = CAST(0 AS BIGINT) AND ((t1."v" / CAST(10000 AS BIGINT)) - (((t1."v" / CAST(10000 AS BIGINT)) / CAST(400 AS BIGINT)) * CAST(400 AS BIGINT))) <> CAST(0 AS BIGINT)
UNION
SELECT DISTINCT t0."id" AS "id" FROM "evaluation_day" AS t0 JOIN "reference_date__day" AS t1 ON t1."id" = t0."id" WHERE (t1."v" / CAST(10000 AS BIGINT)) < CAST(1 AS BIGINT)
UNION
SELECT DISTINCT t0."id" AS "id" FROM "evaluation_day" AS t0 JOIN "reference_date__day" AS t1 ON t1."id" = t0."id" WHERE (t1."v" / CAST(10000 AS BIGINT)) > CAST(9999 AS BIGINT)
UNION
SELECT DISTINCT t0."id" AS "id" FROM "evaluation_day" AS t0 JOIN "reference_date__day" AS t1 ON t1."id" = t0."id" WHERE ((t1."v" - ((t1."v" / CAST(10000 AS BIGINT)) * CAST(10000 AS BIGINT))) / CAST(100 AS BIGINT)) > CAST(12 AS BIGINT)
UNION
SELECT DISTINCT t0."id" AS "id" FROM "evaluation_day" AS t0 JOIN "reference_date__day" AS t1 ON t1."id" = t0."id" WHERE ((t1."v" - ((t1."v" / CAST(10000 AS BIGINT)) * CAST(10000 AS BIGINT))) - (((t1."v" - ((t1."v" / CAST(10000 AS BIGINT)) * CAST(10000 AS BIGINT))) / CAST(100 AS BIGINT)) * CAST(100 AS BIGINT))) < CAST(1 AS BIGINT)
UNION
SELECT DISTINCT t0."id" AS "id" FROM "evaluation_day" AS t0 JOIN "reference_date__day" AS t1 ON t1."id" = t0."id" WHERE ((t1."v" - ((t1."v" / CAST(10000 AS BIGINT)) * CAST(10000 AS BIGINT))) - (((t1."v" - ((t1."v" / CAST(10000 AS BIGINT)) * CAST(10000 AS BIGINT))) / CAST(100 AS BIGINT)) * CAST(100 AS BIGINT))) > CAST(31 AS BIGINT)
UNION
SELECT DISTINCT t0."id" AS "id" FROM "evaluation_day" AS t0 JOIN "reference_date__day" AS t1 ON t1."id" = t0."id" WHERE ((t1."v" - ((t1."v" / CAST(10000 AS BIGINT)) * CAST(10000 AS BIGINT))) / CAST(100 AS BIGINT)) = CAST(4 AS BIGINT) AND ((t1."v" - ((t1."v" / CAST(10000 AS BIGINT)) * CAST(10000 AS BIGINT))) - (((t1."v" - ((t1."v" / CAST(10000 AS BIGINT)) * CAST(10000 AS BIGINT))) / CAST(100 AS BIGINT)) * CAST(100 AS BIGINT))) > CAST(30 AS BIGINT)
UNION
SELECT DISTINCT t0."id" AS "id" FROM "evaluation_day" AS t0 JOIN "reference_date__day" AS t1 ON t1."id" = t0."id" WHERE ((t1."v" - ((t1."v" / CAST(10000 AS BIGINT)) * CAST(10000 AS BIGINT))) / CAST(100 AS BIGINT)) = CAST(6 AS BIGINT) AND ((t1."v" - ((t1."v" / CAST(10000 AS BIGINT)) * CAST(10000 AS BIGINT))) - (((t1."v" - ((t1."v" / CAST(10000 AS BIGINT)) * CAST(10000 AS BIGINT))) / CAST(100 AS BIGINT)) * CAST(100 AS BIGINT))) > CAST(30 AS BIGINT)
UNION
SELECT DISTINCT t0."id" AS "id" FROM "evaluation_day" AS t0 JOIN "reference_date__day" AS t1 ON t1."id" = t0."id" WHERE ((t1."v" - ((t1."v" / CAST(10000 AS BIGINT)) * CAST(10000 AS BIGINT))) / CAST(100 AS BIGINT)) = CAST(9 AS BIGINT) AND ((t1."v" - ((t1."v" / CAST(10000 AS BIGINT)) * CAST(10000 AS BIGINT))) - (((t1."v" - ((t1."v" / CAST(10000 AS BIGINT)) * CAST(10000 AS BIGINT))) / CAST(100 AS BIGINT)) * CAST(100 AS BIGINT))) > CAST(30 AS BIGINT)
UNION
SELECT DISTINCT t0."id" AS "id" FROM "evaluation_day" AS t0 JOIN "reference_date__day" AS t1 ON t1."id" = t0."id" WHERE ((t1."v" - ((t1."v" / CAST(10000 AS BIGINT)) * CAST(10000 AS BIGINT))) / CAST(100 AS BIGINT)) = CAST(11 AS BIGINT) AND ((t1."v" - ((t1."v" / CAST(10000 AS BIGINT)) * CAST(10000 AS BIGINT))) - (((t1."v" - ((t1."v" / CAST(10000 AS BIGINT)) * CAST(10000 AS BIGINT))) / CAST(100 AS BIGINT)) * CAST(100 AS BIGINT))) > CAST(30 AS BIGINT)
UNION
SELECT DISTINCT t0."id" AS "id" FROM "evaluation_day" AS t0 JOIN "reference_date__day" AS t1 ON t1."id" = t0."id" WHERE ((t1."v" - ((t1."v" / CAST(10000 AS BIGINT)) * CAST(10000 AS BIGINT))) / CAST(100 AS BIGINT)) = CAST(2 AS BIGINT) AND ((t1."v" - ((t1."v" / CAST(10000 AS BIGINT)) * CAST(10000 AS BIGINT))) - (((t1."v" - ((t1."v" / CAST(10000 AS BIGINT)) * CAST(10000 AS BIGINT))) / CAST(100 AS BIGINT)) * CAST(100 AS BIGINT))) > CAST(29 AS BIGINT);

CREATE MATERIALIZED VIEW "supersession_cycle" AS
SELECT DISTINCT t0."a" AS "decision" FROM "replaces" AS t0 WHERE t0."b" = t0."a";

CREATE MATERIALIZED VIEW "supersession_cycle__witness" AS
SELECT DISTINCT t0."a" AS "v_a" FROM "replaces" AS t0 WHERE t0."b" = t0."a";

CREATE MATERIALIZED VIEW "was_replaced" AS
SELECT DISTINCT t0."decision" AS "decision", t0."on" AS "on" FROM "replaced" AS t0;

CREATE MATERIALIZED VIEW "window_inverted" AS
SELECT DISTINCT t0."id" AS "decision" FROM "decision__valid_from_day" AS t0 JOIN "decision__valid_until_day" AS t1 ON t1."id" = t0."id" WHERE t1."v" <= t0."v";

CREATE MATERIALIZED VIEW "quoted_costs" AS
SELECT DISTINCT t0."application" AS "application", COALESCE(g0.r, CAST(0 AS BIGINT)) AS "cents" FROM "has_quote" AS t0 LEFT JOIN (SELECT "application" AS k0, CAST(SUM("cents") AS BIGINT) AS r FROM "line" GROUP BY "application") AS g0 ON g0.k0 = t0."application";

CREATE MATERIALIZED VIEW "quoted_costs__witness" AS
SELECT DISTINCT t0."application" AS "v_a", COALESCE(g0.r, CAST(0 AS BIGINT)) AS "v_t" FROM "has_quote" AS t0 LEFT JOIN (SELECT "application" AS k0, CAST(SUM("cents") AS BIGINT) AS r FROM "line" GROUP BY "application") AS g0 ON g0.k0 = t0."application";

CREATE MATERIALIZED VIEW "costs_mismatch" AS
SELECT DISTINCT t0."application" AS "application", t1."v" AS "claimed", t0."cents" AS "quoted" FROM "quoted_costs" AS t0 JOIN "application__claimed_costs" AS t1 ON t1."id" = t0."application" WHERE t1."v" <> t0."cents";

CREATE MATERIALIZED VIEW "costs_mismatch__witness" AS
SELECT DISTINCT t0."application" AS "v_a", t0."cents" AS "v_q", t1."v" AS "v_x" FROM "quoted_costs" AS t0 JOIN "application__claimed_costs" AS t1 ON t1."id" = t0."application" WHERE t1."v" <> t0."cents";

CREATE MATERIALIZED VIEW "in_force_on" AS
SELECT DISTINCT t0."decision" AS "decision", t0."on" AS "on" FROM "took_effect" AS t0 LEFT JOIN "ended" AS n0 ON n0."decision" = t0."decision" AND n0."on" = t0."on" LEFT JOIN "was_replaced" AS n1 ON n1."decision" = t0."decision" AND n1."on" = t0."on" WHERE n0."decision" IS NULL AND n1."decision" IS NULL;

CREATE MATERIALIZED VIEW "in_force_on__witness" AS
SELECT DISTINCT t0."decision" AS "v_d", t0."on" AS "v_r" FROM "took_effect" AS t0 LEFT JOIN "ended" AS n0 ON n0."decision" = t0."decision" AND n0."on" = t0."on" LEFT JOIN "was_replaced" AS n1 ON n1."decision" = t0."decision" AND n1."on" = t0."on" WHERE n0."decision" IS NULL AND n1."decision" IS NULL;

CREATE MATERIALIZED VIEW "decided_parameter" AS
SELECT DISTINCT t0."id" AS "parameter", t0."v" AS "decision", t1."on" AS "on" FROM "scheme_parameter__decision" AS t0 JOIN "in_force_on" AS t1 ON t1."decision" = t0."v";

CREATE MATERIALIZED VIEW "decided_parameter__witness" AS
SELECT DISTINCT t0."v" AS "v_d", t0."id" AS "v_p", t1."on" AS "v_r" FROM "scheme_parameter__decision" AS t0 JOIN "in_force_on" AS t1 ON t1."decision" = t0."v";

CREATE MATERIALIZED VIEW "eligible_costs" AS
SELECT DISTINCT t0."application" AS "application", COALESCE(g0.r, CAST(0 AS BIGINT)) AS "cents" FROM "has_quote" AS t0 LEFT JOIN (SELECT "application" AS k0, CAST(SUM("cents") AS BIGINT) AS r FROM "eligible_line" GROUP BY "application") AS g0 ON g0.k0 = t0."application";

CREATE MATERIALIZED VIEW "eligible_costs__witness" AS
SELECT DISTINCT t0."application" AS "v_a", COALESCE(g0.r, CAST(0 AS BIGINT)) AS "v_t" FROM "has_quote" AS t0 LEFT JOIN (SELECT "application" AS k0, CAST(SUM("cents") AS BIGINT) AS r FROM "eligible_line" GROUP BY "application") AS g0 ON g0.k0 = t0."application";

CREATE MATERIALIZED VIEW "end_not_recorded" AS
SELECT DISTINCT t0."id" AS "interval" FROM "std_time_interval_on_axis" AS t0 LEFT JOIN "end_stated" AS n0 ON n0."interval" = t0."id" LEFT JOIN "interval__unbounded" AS n1 ON n1."id" = t0."id" AND n1."v" = 'end' WHERE n0."interval" IS NULL AND n1."id" IS NULL;

CREATE MATERIALIZED VIEW "extension_without_end" AS
SELECT DISTINCT t0."id" AS "interval" FROM "interval__extension_end" AS t0 JOIN "end_not_recorded" AS t1 ON t1."interval" = t0."id"
UNION
SELECT DISTINCT t0."id" AS "interval" FROM "interval__extension_end" AS t0 JOIN "interval__unbounded" AS t1 ON t1."id" = t0."id" AND t1."v" = 'end';

CREATE MATERIALIZED VIEW "has_decision_in_force" AS
SELECT DISTINCT t0."parameter" AS "parameter", t0."on" AS "on" FROM "decided_parameter" AS t0;

CREATE MATERIALIZED VIEW "statement_in_good_standing" AS
SELECT DISTINCT t0."v" AS "statement" FROM "status_lookup__statement" AS t0 JOIN "status_lookup__status" AS t1 ON t1."id" = t0."id" AND t1."v" = 'valid' LEFT JOIN "statement_withdrawn" AS n0 ON n0."statement" = t0."v" WHERE n0."statement" IS NULL;

CREATE MATERIALIZED VIEW "same_subject" AS
SELECT DISTINCT t0."node" AS "node", t0."identifier" AS "identifier", t0."other_node" AS "other_node", t0."other_identifier" AS "other_identifier" FROM "stated" AS t0 JOIN "statement_authorised" AS t1 ON t1."statement" = t0."statement" JOIN "statement_in_good_standing" AS t2 ON t2."statement" = t0."statement";

CREATE MATERIALIZED VIEW "identified" AS
SELECT DISTINCT t0."id" AS "credential", t2."other_identifier" AS "person" FROM "credential__issuer" AS t0 JOIN "credential__subject" AS t1 ON t1."id" = t0."id" JOIN "same_subject" AS t2 ON t2."node" = t0."v" AND t2."identifier" = t1."v" AND t2."other_node" = 'https://municipality.invented.example';

CREATE MATERIALIZED VIEW "in_force_without_decider" AS
SELECT DISTINCT t0."decision" AS "decision", t0."on" AS "on" FROM "in_force_on" AS t0 LEFT JOIN "has_decider" AS n0 ON n0."decision" = t0."decision" WHERE n0."decision" IS NULL;

CREATE MATERIALIZED VIEW "in_force_without_decider__witness" AS
SELECT DISTINCT t0."decision" AS "v_d", t0."on" AS "v_r" FROM "in_force_on" AS t0 LEFT JOIN "has_decider" AS n0 ON n0."decision" = t0."decision" WHERE n0."decision" IS NULL;

CREATE MATERIALIZED VIEW "in_force_without_start" AS
SELECT DISTINCT t0."id" AS "decision" FROM "decision__state" AS t0 LEFT JOIN "has_start" AS n0 ON n0."decision" = t0."id" WHERE t0."v" = 'in_force' AND n0."decision" IS NULL;

CREATE MATERIALIZED VIEW "in_force_without_start__witness" AS
SELECT DISTINCT t0."id" AS "v_d" FROM "decision__state" AS t0 LEFT JOIN "has_start" AS n0 ON n0."decision" = t0."id" WHERE t0."v" = 'in_force' AND n0."decision" IS NULL;

CREATE MATERIALIZED VIEW "in_good_standing" AS
SELECT DISTINCT t0."v" AS "credential" FROM "status_lookup__credential" AS t0 JOIN "status_lookup__status" AS t1 ON t1."id" = t0."id" AND t1."v" = 'valid' LEFT JOIN "status_withdrawn" AS n0 ON n0."credential" = t0."v" WHERE n0."credential" IS NULL;

CREATE MATERIALIZED VIEW "income_not_received" AS
SELECT DISTINCT t0."id" AS "application", t0."v" AS "household" FROM "application__household" AS t0 LEFT JOIN "has_income_statement" AS n0 ON n0."household" = t0."v" WHERE n0."household" IS NULL;

CREATE MATERIALIZED VIEW "income_not_received__witness" AS
SELECT DISTINCT t0."id" AS "v_a", t0."v" AS "v_h" FROM "application__household" AS t0 LEFT JOIN "has_income_statement" AS n0 ON n0."household" = t0."v" WHERE n0."household" IS NULL;

CREATE MATERIALIZED VIEW "income_missing" AS
SELECT DISTINCT t0."application" AS "application" FROM "income_not_received" AS t0;

CREATE MATERIALIZED VIEW "is_identified" AS
SELECT DISTINCT t0."credential" AS "credential" FROM "identified" AS t0;

CREATE MATERIALIZED VIEW "start_not_recorded" AS
SELECT DISTINCT t0."id" AS "interval" FROM "std_time_interval_on_axis" AS t0 LEFT JOIN "start_stated" AS n0 ON n0."interval" = t0."id" LEFT JOIN "interval__unbounded" AS n1 ON n1."id" = t0."id" AND n1."v" = 'start' WHERE n0."interval" IS NULL AND n1."id" IS NULL;

CREATE MATERIALIZED VIEW "judgement" AS
SELECT DISTINCT t0."interval" AS "interval", t0."at" AS "at", 'negative' AS "value", 'ended' AS "reason" FROM "ended_at" AS t0 JOIN "std_time_interval_end" AS t1 ON t1."id" = t0."interval" LEFT JOIN "extension_stated" AS n0 ON n0."interval" = t0."interval" WHERE n0."interval" IS NULL
UNION
SELECT DISTINCT t0."id" AS "interval", t1."id" AS "at", 'unknown' AS "value", 'start_not_recorded' AS "reason" FROM "std_time_interval_on_axis" AS t0 JOIN "std_time_reference_point_on_axis" AS t1 ON t1."v" = t0."v" JOIN "start_not_recorded" AS t2 ON t2."interval" = t0."id" JOIN "interval__unbounded" AS t3 ON t3."id" = t0."id" AND t3."v" = 'end'
UNION
SELECT DISTINCT t0."interval" AS "interval", t0."at" AS "at", 'no_end' AS "value", 'without_end' AS "reason" FROM "holds_at" AS t0 JOIN "std_time_reference_point_position" AS t1 ON t1."id" = t0."at" JOIN "interval__unbounded" AS t2 ON t2."id" = t0."interval" AND t2."v" = 'end'
UNION
SELECT DISTINCT t0."interval" AS "interval", t0."at" AS "at", 'attention' AS "value", 'end_within_horizon' AS "reason" FROM "holds_at" AS t0 JOIN "std_time_reference_point_position" AS t1 ON t1."id" = t0."at" JOIN "std_time_reference_point_horizon" AS t2 ON t2."id" = t0."at" JOIN "std_time_interval_end" AS t3 ON t3."id" = t0."interval" WHERE t1."v" < t3."v" AND t3."v" <= (t1."v" + t2."v")
UNION
SELECT DISTINCT t0."interval" AS "interval", t0."at" AS "at", 'positive' AS "value", 'end_beyond_horizon' AS "reason" FROM "holds_at" AS t0 JOIN "std_time_reference_point_position" AS t1 ON t1."id" = t0."at" JOIN "std_time_reference_point_horizon" AS t2 ON t2."id" = t0."at" JOIN "std_time_interval_end" AS t3 ON t3."id" = t0."interval" WHERE (t1."v" + t2."v") < t3."v"
UNION
SELECT DISTINCT t0."interval" AS "interval", t0."at" AS "at", 'negative' AS "value", 'extension_ended' AS "reason" FROM "ended_at" AS t0 JOIN "std_time_reference_point_position" AS t1 ON t1."id" = t0."at" JOIN "interval__extension_end" AS t2 ON t2."id" = t0."interval" WHERE t2."v" <= t1."v"
UNION
SELECT DISTINCT t0."interval" AS "interval", t0."at" AS "at", 'attention' AS "value", 'in_extension' AS "reason" FROM "in_extension" AS t0 JOIN "interval__extension_end" AS t1 ON t1."id" = t0."interval"
UNION
SELECT DISTINCT t0."id" AS "interval", t1."id" AS "at", 'not_begun' AS "value", 'start_ahead' AS "reason" FROM "std_time_interval_on_axis" AS t0 JOIN "std_time_reference_point_on_axis" AS t1 ON t1."v" = t0."v" JOIN "std_time_reference_point_position" AS t2 ON t2."id" = t1."id" JOIN "std_time_interval_start" AS t3 ON t3."id" = t0."id" JOIN "std_time_interval_end" AS t4 ON t4."id" = t0."id" WHERE t2."v" < t3."v" AND t2."v" < t4."v"
UNION
SELECT DISTINCT t0."id" AS "interval", t1."id" AS "at", 'not_begun' AS "value", 'start_ahead' AS "reason" FROM "std_time_interval_on_axis" AS t0 JOIN "std_time_reference_point_on_axis" AS t1 ON t1."v" = t0."v" JOIN "std_time_reference_point_position" AS t2 ON t2."id" = t1."id" JOIN "std_time_interval_start" AS t3 ON t3."id" = t0."id" JOIN "interval__unbounded" AS t4 ON t4."id" = t0."id" AND t4."v" = 'end' WHERE t2."v" < t3."v"
UNION
SELECT DISTINCT t0."id" AS "interval", t1."id" AS "at", 'not_begun' AS "value", 'start_ahead' AS "reason" FROM "std_time_interval_on_axis" AS t0 JOIN "std_time_reference_point_on_axis" AS t1 ON t1."v" = t0."v" JOIN "std_time_reference_point_position" AS t2 ON t2."id" = t1."id" JOIN "std_time_interval_start" AS t3 ON t3."id" = t0."id" JOIN "end_not_recorded" AS t4 ON t4."interval" = t0."id" WHERE t2."v" < t3."v"
UNION
SELECT DISTINCT t0."interval" AS "interval", t0."at" AS "at", 'unknown' AS "value", 'end_not_recorded' AS "reason" FROM "begun_at" AS t0 JOIN "std_time_reference_point_position" AS t1 ON t1."id" = t0."at" JOIN "end_not_recorded" AS t2 ON t2."interval" = t0."interval"
UNION
SELECT DISTINCT t0."id" AS "interval", t1."id" AS "at", 'unknown' AS "value", 'end_not_recorded' AS "reason" FROM "std_time_interval_on_axis" AS t0 JOIN "std_time_reference_point_on_axis" AS t1 ON t1."v" = t0."v" JOIN "start_not_recorded" AS t2 ON t2."interval" = t0."id" JOIN "end_not_recorded" AS t3 ON t3."interval" = t0."id"
UNION
SELECT DISTINCT t0."id" AS "interval", t1."id" AS "at", 'unknown' AS "value", 'start_not_recorded' AS "reason" FROM "std_time_interval_on_axis" AS t0 JOIN "std_time_reference_point_on_axis" AS t1 ON t1."v" = t0."v" JOIN "std_time_reference_point_position" AS t2 ON t2."id" = t1."id" JOIN "start_not_recorded" AS t3 ON t3."interval" = t0."id" JOIN "std_time_interval_end" AS t4 ON t4."id" = t0."id" WHERE t2."v" < t4."v";

CREATE MATERIALIZED VIEW "known_from_not_recorded" AS
SELECT DISTINCT t0."id" AS "interval" FROM "std_time_interval_on_axis" AS t0 LEFT JOIN "known_from_stated" AS n0 ON n0."interval" = t0."id" WHERE n0."interval" IS NULL;

CREATE MATERIALIZED VIEW "ledger_paid" AS
SELECT DISTINCT t0."application" AS "application", COALESCE(g0.r, CAST(0 AS BIGINT)) AS "cents" FROM "paid" AS t0 LEFT JOIN (SELECT "application" AS k0, CAST(SUM("cents") AS BIGINT) AS r FROM "ledger_line" GROUP BY "application") AS g0 ON g0.k0 = t0."application";

CREATE MATERIALIZED VIEW "ledger_paid__witness" AS
SELECT DISTINCT t0."application" AS "v_a", COALESCE(g0.r, CAST(0 AS BIGINT)) AS "v_t" FROM "paid" AS t0 LEFT JOIN (SELECT "application" AS k0, CAST(SUM("cents") AS BIGINT) AS r FROM "ledger_line" GROUP BY "application") AS g0 ON g0.k0 = t0."application";

CREATE MATERIALIZED VIEW "not_disclosed" AS
SELECT DISTINCT t0."id" AS "claim" FROM "credential_claim" AS t0 LEFT JOIN "disclosed" AS n0 ON n0."claim" = t0."id" WHERE n0."claim" IS NULL;

CREATE MATERIALIZED VIEW "not_disclosed__witness" AS
SELECT DISTINCT t0."id" AS "v_k" FROM "credential_claim" AS t0 LEFT JOIN "disclosed" AS n0 ON n0."claim" = t0."id" WHERE n0."claim" IS NULL;

CREATE MATERIALIZED VIEW "quote_missing" AS
SELECT DISTINCT t0."id" AS "application" FROM "application" AS t0 LEFT JOIN "has_quote" AS n0 ON n0."application" = t0."id" WHERE n0."application" IS NULL;

CREATE MATERIALIZED VIEW "quote_missing__witness" AS
SELECT DISTINCT t0."id" AS "v_a" FROM "application" AS t0 LEFT JOIN "has_quote" AS n0 ON n0."application" = t0."id" WHERE n0."application" IS NULL;

CREATE MATERIALIZED VIEW "status_lookup_not_of_one" AS
SELECT DISTINCT t0."id" AS "lookup" FROM "status_lookup" AS t0 LEFT JOIN "looked_up" AS n0 ON n0."lookup" = t0."id" WHERE n0."lookup" IS NULL
UNION
SELECT DISTINCT t0."id" AS "lookup" FROM "status_lookup__credential" AS t0 JOIN "status_lookup__statement" AS t1 ON t1."id" = t0."id";

CREATE MATERIALIZED VIEW "superseded_in_force" AS
SELECT DISTINCT t0."id" AS "decision", t1."on" AS "on" FROM "decision__state" AS t0 JOIN "in_force_on" AS t1 ON t1."decision" = t0."id" LEFT JOIN "has_successor" AS n0 ON n0."decision" = t0."id" WHERE t0."v" = 'superseded' AND n0."decision" IS NULL;

CREATE MATERIALIZED VIEW "superseded_in_force__witness" AS
SELECT DISTINCT t0."id" AS "v_d", t1."on" AS "v_r" FROM "decision__state" AS t0 JOIN "in_force_on" AS t1 ON t1."decision" = t0."id" LEFT JOIN "has_successor" AS n0 ON n0."decision" = t0."id" WHERE t0."v" = 'superseded' AND n0."decision" IS NULL;

CREATE MATERIALIZED VIEW "withdrawn_without_start" AS
SELECT DISTINCT t0."id" AS "decision" FROM "decision__state" AS t0 LEFT JOIN "has_start" AS n0 ON n0."decision" = t0."id" WHERE t0."v" = 'withdrawn' AND n0."decision" IS NULL;

CREATE MATERIALIZED VIEW "withdrawn_without_start__witness" AS
SELECT DISTINCT t0."id" AS "v_d" FROM "decision__state" AS t0 LEFT JOIN "has_start" AS n0 ON n0."decision" = t0."id" WHERE t0."v" = 'withdrawn' AND n0."decision" IS NULL;

CREATE MATERIALIZED VIEW "assessment" AS
SELECT DISTINCT t0."application" AS "application", 'unknown' AS "state", 'income_statement_not_received' AS "reason" FROM "income_missing" AS t0
UNION
SELECT DISTINCT t0."application" AS "application", 'unknown' AS "state", 'quote_not_received' AS "reason" FROM "quote_missing" AS t0
UNION
SELECT DISTINCT t0."id" AS "application", 'known' AS "state", '' AS "reason" FROM "application" AS t0 LEFT JOIN "income_missing" AS n0 ON n0."application" = t0."id" LEFT JOIN "quote_missing" AS n1 ON n1."application" = t0."id" WHERE n0."application" IS NULL AND n1."application" IS NULL;

CREATE MATERIALIZED VIEW "assessment_1__witness" AS
SELECT DISTINCT t0."application" AS "v_a" FROM "income_missing" AS t0;

CREATE MATERIALIZED VIEW "assessment_2__witness" AS
SELECT DISTINCT t0."application" AS "v_a" FROM "quote_missing" AS t0;

CREATE MATERIALIZED VIEW "assessment_3__witness" AS
SELECT DISTINCT t0."id" AS "v_a" FROM "application" AS t0 LEFT JOIN "income_missing" AS n0 ON n0."application" = t0."id" LEFT JOIN "quote_missing" AS n1 ON n1."application" = t0."id" WHERE n0."application" IS NULL AND n1."application" IS NULL;

CREATE MATERIALIZED VIEW "assessment__total" AS
SELECT DISTINCT k."id" AS "application" FROM "application" AS k
LEFT JOIN "assessment" AS o ON o."application" = k."id" WHERE o."application" IS NULL
UNION
SELECT DISTINCT o."application" FROM "assessment" AS o
LEFT JOIN "application" AS k ON k."id" = o."application" WHERE k."id" IS NULL;

CREATE MATERIALIZED VIEW "assessment__state" AS
SELECT "application" FROM "assessment" GROUP BY "application" HAVING COUNT(DISTINCT "state") > 1;

CREATE MATERIALIZED VIEW "assessed_costs" AS
SELECT DISTINCT t0."application" AS "application", t1."cents" AS "cents" FROM "assessment" AS t0 JOIN "eligible_costs" AS t1 ON t1."application" = t0."application" WHERE t0."state" = 'known' AND t0."reason" = '';

CREATE MATERIALIZED VIEW "assessed_costs__witness" AS
SELECT DISTINCT t0."application" AS "v_a", t1."cents" AS "v_c" FROM "assessment" AS t0 JOIN "eligible_costs" AS t1 ON t1."application" = t0."application" WHERE t0."state" = 'known' AND t0."reason" = '';

CREATE MATERIALIZED VIEW "assessed_income" AS
SELECT DISTINCT t0."application" AS "application", t3."v" AS "cents" FROM "assessment" AS t0 JOIN "application__household" AS t1 ON t1."id" = t0."application" JOIN "income_statement__household" AS t2 ON t2."v" = t1."v" JOIN "income_statement__income" AS t3 ON t3."id" = t2."id" WHERE t0."state" = 'known' AND t0."reason" = '';

CREATE MATERIALIZED VIEW "claim_assessment" AS
SELECT DISTINCT t0."claim" AS "claim", 'unknown' AS "state", 'not_disclosed' AS "reason" FROM "not_disclosed" AS t0
UNION
SELECT DISTINCT t0."id" AS "claim", 'unknown' AS "state", 'issuer_not_authorised' AS "reason" FROM "credential_claim" AS t0 LEFT JOIN "authorised" AS n0 ON n0."claim" = t0."id" WHERE n0."claim" IS NULL
UNION
SELECT DISTINCT t0."id" AS "claim", 'unknown' AS "state", 'status_not_valid' AS "reason" FROM "credential_claim__credential" AS t0 LEFT JOIN "in_good_standing" AS n0 ON n0."credential" = t0."v" WHERE n0."credential" IS NULL
UNION
SELECT DISTINCT t0."claim" AS "claim", 'known' AS "state", '' AS "reason" FROM "disclosed" AS t0 JOIN "authorised" AS t1 ON t1."claim" = t0."claim" JOIN "credential_claim__credential" AS t2 ON t2."id" = t0."claim" JOIN "in_good_standing" AS t3 ON t3."credential" = t2."v";

CREATE MATERIALIZED VIEW "claim_assessment__total" AS
SELECT DISTINCT k."id" AS "claim" FROM "credential_claim" AS k
LEFT JOIN "claim_assessment" AS o ON o."claim" = k."id" WHERE o."claim" IS NULL
UNION
SELECT DISTINCT o."claim" FROM "claim_assessment" AS o
LEFT JOIN "credential_claim" AS k ON k."id" = o."claim" WHERE k."id" IS NULL;

CREATE MATERIALIZED VIEW "claim_assessment__state" AS
SELECT "claim" FROM "claim_assessment" GROUP BY "claim" HAVING COUNT(DISTINCT "state") > 1;

CREATE MATERIALIZED VIEW "attested" AS
SELECT DISTINCT t2."v" AS "node", t3."v" AS "subject", t4."v" AS "attribute", t5."v" AS "value" FROM "claim_assessment" AS t0 JOIN "credential_claim__credential" AS t1 ON t1."id" = t0."claim" JOIN "credential__issuer" AS t2 ON t2."id" = t1."v" JOIN "credential__subject" AS t3 ON t3."id" = t1."v" JOIN "credential_claim__attribute" AS t4 ON t4."id" = t0."claim" JOIN "credential_claim__value" AS t5 ON t5."id" = t0."claim" WHERE t0."state" = 'known' AND t0."reason" = '';

CREATE MATERIALIZED VIEW "subject_identification" AS
SELECT DISTINCT t0."id" AS "credential", 'unknown' AS "state", 'no_identity_statement' AS "reason" FROM "credential" AS t0 LEFT JOIN "named_here" AS n0 ON n0."credential" = t0."id" WHERE n0."credential" IS NULL
UNION
SELECT DISTINCT t0."credential" AS "credential", 'unknown' AS "state", 'statement_issuer_not_authorised' AS "reason" FROM "names_here" AS t0 LEFT JOIN "is_identified" AS n0 ON n0."credential" = t0."credential" LEFT JOIN "scoped" AS n1 ON n1."statement" = t0."statement" WHERE n0."credential" IS NULL AND n1."statement" IS NULL
UNION
SELECT DISTINCT t0."credential" AS "credential", 'unknown' AS "state", 'statement_issuance_not_established' AS "reason" FROM "names_here" AS t0 JOIN "scoped" AS t1 ON t1."statement" = t0."statement" JOIN "statement_seen" AS t2 ON t2."statement" = t0."statement" LEFT JOIN "is_identified" AS n0 ON n0."credential" = t0."credential" LEFT JOIN "authoritative" AS n1 ON n1."statement" = t0."statement" WHERE n0."credential" IS NULL AND n1."statement" IS NULL
UNION
SELECT DISTINCT t0."credential" AS "credential", 'unknown' AS "state", 'statement_status_not_valid' AS "reason" FROM "names_here" AS t0 LEFT JOIN "is_identified" AS n0 ON n0."credential" = t0."credential" LEFT JOIN "statement_in_good_standing" AS n1 ON n1."statement" = t0."statement" WHERE n0."credential" IS NULL AND n1."statement" IS NULL
UNION
SELECT DISTINCT t0."credential" AS "credential", 'known' AS "state", '' AS "reason" FROM "identified" AS t0;

CREATE MATERIALIZED VIEW "subject_identification__total" AS
SELECT DISTINCT k."id" AS "credential" FROM "credential" AS k
LEFT JOIN "subject_identification" AS o ON o."credential" = k."id" WHERE o."credential" IS NULL
UNION
SELECT DISTINCT o."credential" FROM "subject_identification" AS o
LEFT JOIN "credential" AS k ON k."id" = o."credential" WHERE k."id" IS NULL;

CREATE MATERIALIZED VIEW "subject_identification__state" AS
SELECT "credential" FROM "subject_identification" GROUP BY "credential" HAVING COUNT(DISTINCT "state") > 1;

CREATE MATERIALIZED VIEW "attested_here" AS
SELECT DISTINCT t1."person" AS "person", t4."attribute" AS "attribute", t4."value" AS "value" FROM "subject_identification" AS t0 JOIN "identified" AS t1 ON t1."credential" = t0."credential" JOIN "credential__issuer" AS t2 ON t2."id" = t0."credential" JOIN "credential__subject" AS t3 ON t3."id" = t0."credential" JOIN "attested" AS t4 ON t4."node" = t2."v" AND t4."subject" = t3."v" WHERE t0."state" = 'known' AND t0."reason" = '';

CREATE MATERIALIZED VIEW "undecided_parameter" AS
SELECT DISTINCT t0."id" AS "parameter", t1."id" AS "on" FROM "scheme_parameter" AS t0 JOIN "reference_date" AS t1 ON TRUE LEFT JOIN "has_decision_in_force" AS n0 ON n0."parameter" = t0."id" AND n0."on" = t1."id" WHERE n0."parameter" IS NULL;

CREATE MATERIALIZED VIEW "undecided_parameter__witness" AS
SELECT DISTINCT t0."id" AS "v_p", t1."id" AS "v_r" FROM "scheme_parameter" AS t0 JOIN "reference_date" AS t1 ON TRUE LEFT JOIN "has_decision_in_force" AS n0 ON n0."parameter" = t0."id" AND n0."on" = t1."id" WHERE n0."parameter" IS NULL;
